import java.util.*;

class Solution {
    public int fewestCuts(String s) {
        int n = s.length();
        int[] cut = new int[n + 1];          // cut[i] = min cuts for s[0..i-1]
        for (int i = 0; i <= n; i++) cut[i] = i - 1;   // cut[0] = -1 so a full mirror costs 0
        for (int c = 0; c < n; c++) {
            for (int odd = 0; odd < 2; odd++) {
                int l = c, r = c + odd;      // odd = 0 -> odd length, odd = 1 -> even length
                while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                    cut[r + 1] = Math.min(cut[r + 1], cut[l] + 1);   // s[l..r] is the last piece
                    l--; r++;
                }
            }
        }
        return cut[n];
    }
}

