function fewestCuts(s) {
  const n = s.length;
  const pal = Array.from({length: n}, () => new Array(n).fill(false));
  const cuts = new Array(n).fill(0);
  for (let r = 0; r < n; r++) {
    let best = r;
    for (let l = 0; l <= r; l++) {
      if (s[l] === s[r] && (r - l < 2 || pal[l+1][r-1])) {
        pal[l][r] = true;
        best = Math.min(best, l === 0 ? 0 : cuts[l-1] + 1);
      }
    }
    cuts[r] = best;
  }
  return cuts[n-1];
}
